import SwiftUI
struct RecipeDetailView:View{
 @Environment(AppStore.self)private var store;let recipeID:UUID;@State private var edit=false;@State private var cooking=false;@State private var servings=2
 var recipe:Recipe?{store.recipes.first(where:{$0.id==recipeID})}
 var body:some View{Group{if let r=recipe{ScrollView{VStack(alignment:.leading,spacing:22){RoundedRectangle(cornerRadius:26).fill(.green.opacity(0.12)).frame(height:250).overlay(Image(systemName:"fork.knife").font(.system(size:64)).foregroundStyle(CookTheme.green));Text(r.title).font(CookTheme.title());HStack{Label(r.minutes>0 ? "\(r.minutes) min":"Time unknown",systemImage:"clock");Spacer();Stepper("\(servings) servings",value:$servings,in:1...12)}.font(.subheadline);if r.needsReview{Label("This import needs a quick review.",systemImage:"exclamationmark.circle").foregroundStyle(.orange)};if let s=r.sourceURL,let u=URL(string:s){Link("Open original source",destination:u)};Text("Ingredients").font(.title2.bold());ForEach(r.ingredients){x in HStack{Text(x.name);Spacer();Text(x.amount).foregroundStyle(.secondary)}};Text("Steps").font(.title2.bold());ForEach(Array(r.steps.enumerated()),id:\.element.id){i,s in HStack(alignment:.top){Text("\(i+1)").font(.headline).frame(width:28,height:28).background(.green.opacity(0.12),in:Circle());Text(s.text)}};Button("Start Cooking"){cooking=true}.buttonStyle(PrimaryButtonStyle()).disabled(r.steps.isEmpty);Button("Add ingredients to groceries"){store.addGroceries(from:r,servings:servings)}.buttonStyle(.bordered).frame(maxWidth:.infinity).disabled(r.ingredients.isEmpty)}.padding()}.background(CookTheme.paper).navigationTitle("Recipe").navigationBarTitleDisplayMode(.inline).toolbar{Button{store.toggleFavorite(r.id)}label:{Image(systemName:r.isFavorite ? "heart.fill":"heart")};Button("Edit"){edit=true}}.sheet(isPresented:$edit){NavigationStack{RecipeEditorView(recipe:r)}}.fullScreenCover(isPresented:$cooking){CookingModeView(recipe:r)}.onAppear{servings=max(r.servings,1)}}else{ContentUnavailableView("Recipe unavailable",systemImage:"exclamationmark.triangle")}}}
}
